{"code":"import nanosurf as nsf
import json, time
spm = nsf.SPM()
app = spm.application
scan = app.Scan
zc = app.ZController
res = {}

# stop any running scan
try:
    if scan.IsScanning:
        scan.Stop()
        while scan.IsScanning:
            time.sleep(0.1)
    res["stop"] = "ok"
except Exception as e:
    res["stop"] = f"ERR {e}"

# configure scan geometry and timing
try:
    scan.ImageSize(5e-6, 5e-6)
    res["imagesize_set"] = "ok"
except Exception as e:
    res["imagesize_set"] = f"ERR {type(e).__name__}: {e}"
try:
    scan.Points = 256
    res["points_set"] = "ok"
except Exception as e:
    res["points_set"] = f"ERR {type(e).__name__}: {e}"
try:
    scan.Lines = 256
    res["lines_set"] = "ok"
except Exception as e:
    res["lines_set"] = f"ERR {type(e).__name__}: {e}"
try:
    scan.Scantime = 0.075
    res["scantime_set"] = "ok"
except Exception as e:
    res["scantime_set"] = f"ERR {type(e).__name__}: {e}"

# z-controller gains and setpoint
for attr, val in [("Setpoint", 0.1), ("Pgain", 100.0), ("Igain", 50.0), ("Dgain", 0.0)]:
    try:
        setattr(zc, attr, val)
        res[f"zc_{attr}"] = "ok"
    except Exception as e:
        res[f"zc_{attr}"] = f"ERR {type(e).__name__}: {e}"

time.sleep(0.5)
# readback
for attr in ["Scantime","Points","Lines","IsScanning"]:
    try:
        res["read_scan_"+attr] = str(getattr(scan, attr))
    except Exception as e:
        res["read_scan_"+attr] = f"ERR"
for attr in ["Setpoint","Pgain","Igain","Dgain"]:
    try:
        res["read_zc_"+attr] = str(getattr(zc, attr))
    except Exception as e:
        res["read_zc_"+attr] = "ERR"
try:
    res["read_mode"] = str(app.OperatingMode.OperatingMode)
except Exception as e:
    res["read_mode"] = "ERR"

with open(r'C:\Users\Admin\Desktop\corral\corral\.corral\workspaces\afm_experiment_level_1_task_9-2f6b5839c138e9c4bc89e568\_probe8.txt','w') as f:
    json.dump(res, f, indent=1)
print("done")
"}

